<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(17, 24, 39, 0.92);
      --panel-border: rgba(148, 163, 184, 0.24);
      --text: #e5eefb;
      --muted: #94a3b8;
      --accent: #7c3aed;
      --accent-strong: #a78bfa;
      --success: #34d399;
      --error: #fda4af;
      --shadow: 0 24px 60px rgba(2, 6, 23, 0.48);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 58, 237, 0.24), transparent 36%),
        linear-gradient(180deg, #111827 0%, var(--bg) 100%);
      color: var(--text);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 0.75rem;
      background: #ffffff;
      color: #111827;
      transform: translateY(-180%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    main {
      display: grid;
      place-items: center;
      min-height: 100vh;
      padding: 2rem 1rem;
    }

    .card {
      width: min(100%, 38rem);
      padding: 2rem;
      border: 1px solid var(--panel-border);
      border-radius: 1.5rem;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(12px);
    }

    h1 {
      margin: 0 0 0.75rem;
      font-size: clamp(1.9rem, 4vw, 2.5rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 1.75rem;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1.5rem;
    }

    .form-field {
      padding: 1.25rem;
      border: 1px solid rgba(124, 58, 237, 0.35);
      border-radius: 1rem;
      background: rgba(15, 23, 42, 0.78);
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      margin-bottom: 0.75rem;
      font-size: 1.1rem;
      font-weight: 700;
    }

    .required-mark {
      color: var(--accent-strong);
    }

    .help-text,
    .status-text {
      margin: 0 0 1rem;
      color: var(--muted);
      line-height: 1.5;
    }

    .status-text {
      min-height: 1.5rem;
      margin-top: 1rem;
      margin-bottom: 0;
    }

    .status-text[data-state="error"] {
      color: var(--error);
    }

    .status-text[data-state="success"] {
      color: var(--success);
    }

    .radio-option + .radio-option {
      margin-top: 0.75rem;
    }

    .radio-option label {
      display: flex;
      align-items: center;
      gap: 0.85rem;
      width: 100%;
      padding: 0.95rem 1rem;
      border: 1px solid rgba(148, 163, 184, 0.22);
      border-radius: 0.9rem;
      background: rgba(30, 41, 59, 0.72);
      cursor: pointer;
      transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;
    }

    .radio-option label:hover {
      border-color: rgba(167, 139, 250, 0.72);
      background: rgba(51, 65, 85, 0.9);
      transform: translateY(-1px);
    }

    input[type="radio"] {
      margin: 0;
      accent-color: var(--accent-strong);
      inline-size: 1.15rem;
      block-size: 1.15rem;
      flex: 0 0 auto;
    }

    input[type="radio"]:focus-visible {
      outline: 3px solid rgba(191, 219, 254, 0.95);
      outline-offset: 3px;
    }

    .radio-option input[type="radio"]:checked + span {
      color: #ffffff;
      font-weight: 700;
    }

    button[type="submit"] {
      justify-self: start;
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.4rem;
      font-size: 1rem;
      font-weight: 700;
      color: #ffffff;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      cursor: pointer;
      box-shadow: 0 14px 30px rgba(124, 58, 237, 0.35);
    }

    button[type="submit"]:focus-visible {
      outline: 3px solid rgba(191, 219, 254, 0.95);
      outline-offset: 4px;
    }

    @media (max-width: 36rem) {
      .card {
        padding: 1.5rem;
      }
    }

    @media (forced-colors: active) {
      .skip-link,
      .card,
      .form-field,
      .radio-option label,
      button[type="submit"] {
        border: 1px solid CanvasText;
        box-shadow: none;
      }

      .radio-option label:hover {
        background: Highlight;
        color: HighlightText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <h1 id="page-title">Notification preferences</h1>
      <p class="intro">Choose one contact method so we know how you would like to receive notifications.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="notification-help notification-status">
            <legend>
              How do you prefer to receive notifications?
              <span class="required-mark" aria-hidden="true">*</span>
            </legend>
            <p class="help-text" id="notification-help">Required field. Select exactly one option.</p>

            <div class="radio-option">
              <label for="notification-email">
                <input id="notification-email" type="radio" name="notificationPreference" value="Email" required>
                <span>Email</span>
              </label>
            </div>

            <div class="radio-option">
              <label for="notification-sms">
                <input id="notification-sms" type="radio" name="notificationPreference" value="SMS" required>
                <span>SMS</span>
              </label>
            </div>

            <div class="radio-option">
              <label for="notification-push">
                <input id="notification-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                <span>Push Notifications</span>
              </label>
            </div>

            <p class="status-text" id="notification-status" aria-live="polite"></p>
          </fieldset>
        </div>

        <button type="submit">Save preference</button>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('notification-form');
    const radios = Array.from(form.elements.notificationPreference);
    const status = document.getElementById('notification-status');

    const setStatus = (message, state) => {
      status.textContent = message;
      status.dataset.state = state;

      for (const radio of radios) {
        if (state === 'error') {
          radio.setAttribute('aria-invalid', 'true');
        } else {
          radio.removeAttribute('aria-invalid');
        }
      }
    };

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const selected = radios.find((radio) => radio.checked);

      if (!selected) {
        setStatus('Error: Select how you prefer to receive notifications.', 'error');
        radios[0].focus();
        return;
      }

      setStatus(`Preference submitted: ${selected.value}.`, 'success');
    });

    for (const radio of radios) {
      radio.addEventListener('change', () => {
        if (radio.checked) {
          setStatus('', '');
        }
      });
    }
  </script>
</body>
</html>
