   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main id="main-content">
     <section class="card" aria-labelledby="page-title">
       <h1 id="page-title">Notification preferences</h1>
       <p class="intro">Choose one contact method so we know how you would like to receive notifications.</p>

       <form id="notification-form" novalidate>
         <div class="form-field">
           <fieldset aria-describedby="notification-help notification-status">
             <legend>
               How do you prefer to receive notifications?
               <span class="required-mark" aria-hidden="true">*</span>
             </legend>
             <p class="help-text" id="notification-help">Required field. Select exactly one option.</p>

             <div class="radio-option">
               <label for="notification-email">
                 <input id="notification-email" type="radio" name="notificationPreference" value="Email" required>
                 <span>Email</span>
               </label>
             </div>

             <div class="radio-option">
               <label for="notification-sms">
                 <input id="notification-sms" type="radio" name="notificationPreference" value="SMS" required>
                 <span>SMS</span>
               </label>
             </div>

             <div class="radio-option">
               <label for="notification-push">
                 <input id="notification-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                 <span>Push Notifications</span>
               </label>
             </div>

             <p class="status-text" id="notification-status" aria-live="polite"></p>
           </fieldset>
         </div>

         <button type="submit">Save preference</button>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('notification-form');
     const radios = Array.from(form.elements.notificationPreference);
     const status = document.getElementById('notification-status');

     const setStatus = (message, state) => {
       status.textContent = message;
       status.dataset.state = state;

       for (const radio of radios) {
         if (state === 'error') {
           radio.setAttribute('aria-invalid', 'true');
         } else {
           radio.removeAttribute('aria-invalid');
         }
       }
     };

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const selected = radios.find((radio) => radio.checked);

       if (!selected) {
         setStatus('Error: Select how you prefer to receive notifications.', 'error');
         radios[0].focus();
         return;
       }

       setStatus(`Preference submitted: ${selected.value}.`, 'success');
     });

     for (const radio of radios) {
       radio.addEventListener('change', () => {
         if (radio.checked) {
           setStatus('', '');
         }
       });
     }
   </script>
 </body>
