     const form = document.getElementById('notification-form');
     const fieldset = document.getElementById('notification-fieldset');
     const radios = Array.from(form.elements.notificationPreference);
     const status = document.getElementById('notification-status');

     const setStatus = (message, state) => {
       status.textContent = message;
       status.dataset.state = state;

        if (state === 'error') {
         fieldset.setAttribute('aria-describedby', 'notification-help notification-status');
       } else {
         fieldset.setAttribute('aria-describedby', 'notification-help');
       }

       for (const radio of radios) {
         if (state === 'error') {
           radio.setAttribute('aria-invalid', 'true');
         } else {
           radio.removeAttribute('aria-invalid');
         }
       }
     };

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const selected = radios.find((radio) => radio.checked);

       if (!selected) {
         setStatus('Error: Select how you prefer to receive notifications.', 'error');
         radios[0].focus();
         return;
       }

       setStatus(`Preference submitted: ${selected.value}.`, 'success');
     });

     for (const radio of radios) {
       radio.addEventListener('change', () => {
         if (radio.checked) {
           setStatus('', '');
         }
       });
     }
